cat > src/cli.rs <<'EOF'
//! Command line interface definition.

use std::ffi::OsString;
use std::path::PathBuf;

use clap::builder::styling::{AnsiColor, Effects, Styles};
use clap::builder::{PossibleValuesParser, StyledStr};
use clap::error::{ContextKind, ContextValue, ErrorKind};
use clap::{value_parser, Arg, ArgAction, ArgGroup, ArgMatches, Command};

/// Supported input encodings.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Encoding {
    Utf8Lossy,
    Utf8,
}

impl Encoding {
    pub const NAMES: [&'static str; 2] = ["utf8-lossy", "utf8"];

    pub fn from_name(name: &str) -> Encoding {
        if name.eq_ignore_ascii_case("utf8") {
            Encoding::Utf8
        } else {
            Encoding::Utf8Lossy
        }
    }
}

/// Shells for which a completion script can be generated.
pub const SHELLS: [&str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

/// Identifiers of the arguments belonging to the main option set.
const OPT_ARGS: [&str; 6] = ["file", "hscale", "vscale", "padding", "encoding", "version"];

fn styles() -> Styles {
    Styles::styled()
        .header(AnsiColor::Yellow.on_default() | Effects::BOLD)
        .usage(AnsiColor::Yellow.on_default() | Effects::BOLD)
        .literal(AnsiColor::Green.on_default() | Effects::BOLD)
        .placeholder(AnsiColor::Cyan.on_default())
        .error(AnsiColor::Red.on_default() | Effects::BOLD)
        .valid(AnsiColor::Green.on_default())
        .invalid(AnsiColor::Yellow.on_default())
}

pub fn build() -> Command {
    Command::new("code-minimap")
        .version(env!("CARGO_PKG_VERSION"))
        .about("A high performance code minimap generator")
        .styles(styles())
        .next_line_help(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("file")
                .value_name("FILE")
                .help("File to read")
                .action(ArgAction::Set)
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("hscale")
                .short('H')
                .long("horizontal-scale")
                .value_name("HSCALE")
                .help("Specify horizontal scale factor")
                .default_value("1.0")
                .action(ArgAction::Set)
                .value_parser(value_parser!(f64)),
        )
        .arg(
            Arg::new("vscale")
                .short('V')
                .long("vertical-scale")
                .value_name("VSCALE")
                .help("Specify vertical scale factor")
                .default_value("1.0")
                .action(ArgAction::Set)
                .value_parser(value_parser!(f64)),
        )
        .arg(
            Arg::new("padding")
                .long("padding")
                .value_name("PADDING")
                .help("Specify padding width")
                .action(ArgAction::Set)
                .value_parser(value_parser!(usize)),
        )
        .arg(
            Arg::new("encoding")
                .long("encoding")
                .value_name("ENCODING")
                .help("Specify input encoding")
                .default_value("utf8-lossy")
                .ignore_case(true)
                .action(ArgAction::Set)
                .value_parser(PossibleValuesParser::new(Encoding::NAMES)),
        )
        .arg(
            Arg::new("version")
                .long("version")
                .help("Print version")
                .action(ArgAction::Version),
        )
        .group(ArgGroup::new("Opt").multiple(true).args(OPT_ARGS))
        .subcommand(
            Command::new("completion")
                .about("Generate shell completion file")
                .arg(
                    Arg::new("shell")
                        .value_name("SHELL")
                        .help("Target shell name")
                        .required(true)
                        .action(ArgAction::Set)
                        .value_parser(PossibleValuesParser::new(SHELLS)),
                ),
        )
}

/// Parse the process arguments, exiting on errors (or help/version requests).
pub fn parse() -> ArgMatches {
    parse_from(std::env::args_os())
}

pub fn parse_from<I, T>(args: I) -> ArgMatches
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
{
    let mut cmd = build();
    match cmd.try_get_matches_from_mut(args) {
        Ok(matches) => matches,
        Err(mut err) => {
            if err.kind() == ErrorKind::UnknownArgument {
                if let Some(usage) = group_usage(&cmd, &err) {
                    err.insert(ContextKind::Usage, ContextValue::StyledStr(usage));
                }
            }
            err.exit()
        }
    }
}

/// When an unknown long argument is reported after some of the main options
/// were already supplied, the usage line lists the whole option group.
fn group_usage(cmd: &Command, err: &clap::Error) -> Option<StyledStr> {
    let usage = match err.get(ContextKind::Usage)? {
        ContextValue::StyledStr(s) => s.to_string(),
        _ => return None,
    };
    let bin = cmd
        .get_bin_name()
        .map(str::to_owned)
        .unwrap_or_else(|| cmd.get_name().to_owned());
    let rest = usage.strip_prefix("Usage: ")?.strip_prefix(bin.as_str())?;
    let rest = rest.strip_prefix(' ').unwrap_or(rest);
    let first = rest.split(' ').next().unwrap_or("");
    if first == "[OPTIONS]" || cmd.get_subcommands().any(|s| s.get_name() == first) {
        return None;
    }

    let mut used_help = false;
    let mut used_opt = false;
    let mut tokens = rest.split(' ').peekable();
    while let Some(tok) = tokens.next() {
        match tok {
            "--help" => used_help = true,
            "[FILE]" | "" => {}
            "<FILE>" => used_opt = true,
            t if t.starts_with("--") => {
                used_opt = true;
                if tokens.peek().map_or(false, |n| n.starts_with('<')) {
                    tokens.next();
                }
            }
            _ => return None,
        }
    }
    if !used_opt {
        return None;
    }

    let styles = cmd.get_styles();
    let header = styles.get_usage();
    let literal = styles.get_literal();
    let placeholder = styles.get_placeholder();
    let members: Vec<String> = OPT_ARGS
        .iter()
        .filter_map(|id| cmd.get_arguments().find(|a| a.get_id() == id))
        .map(|arg| {
            if arg.is_positional() {
                format!("{}", arg.get_value_names().map(|v| v[0].to_string()).unwrap_or_default())
            } else {
                match arg.get_value_names() {
                    Some(names) => format!("--{} <{}>", arg.get_long().unwrap_or(""), names[0]),
                    None => format!("--{}", arg.get_long().unwrap_or("")),
                }
            }
        })
        .collect();

    let mut out = format!("{header}Usage:{header:#} {literal}{bin}{literal:#} ");
    if used_help {
