//! Minimal terminal size detection.
//!
//! Provides the small API surface needed for wrapping help output: the size
//! of the terminal attached to stdout, stderr or stdin (checked in that
//! order).

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

/// Size of the terminal attached to one of the standard streams, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO]
        .into_iter()
        .find_map(size_of_fd)
}

#[cfg(unix)]
fn size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    // SAFETY: `isatty` and `ioctl(TIOCGWINSZ)` only inspect the descriptor
    // and fill in the provided, properly sized `winsize` structure.
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_col > 0 && ws.ws_row > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

#[cfg(not(unix))]
fn size_of_fd(_fd: libc::c_int) -> Option<(Width, Height)> {
    None
}
