//! Minimal terminal size detection.
//!
//! Provides the small API surface needed for wrapping help output: the size
//! of the terminal attached to stdout, stderr or stdin (checked in that
//! order).

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

/// Size of the terminal attached to one of the standard streams, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    // stdout, stderr, stdin
    [1, 2, 0].into_iter().find_map(sys::size_of_fd)
}

#[cfg(any(target_os = "linux", target_os = "android"))]
mod sys {
    use super::{Height, Width};
    use std::os::raw::{c_int, c_ulong, c_ushort};

    #[repr(C)]
    #[derive(Default)]
    struct WinSize {
        ws_row: c_ushort,
        ws_col: c_ushort,
        ws_xpixel: c_ushort,
        ws_ypixel: c_ushort,
    }

    #[cfg(any(
        target_arch = "powerpc",
        target_arch = "powerpc64",
        target_arch = "mips",
        target_arch = "mips64",
        target_arch = "sparc64"
    ))]
    const TIOCGWINSZ: c_ulong = 0x4008_7468;
    #[cfg(not(any(
        target_arch = "powerpc",
        target_arch = "powerpc64",
        target_arch = "mips",
        target_arch = "mips64",
        target_arch = "sparc64"
    )))]
    const TIOCGWINSZ: c_ulong = 0x5413;

    extern "C" {
        fn isatty(fd: c_int) -> c_int;
        fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    }

    pub(super) fn size_of_fd(fd: c_int) -> Option<(Width, Height)> {
        let mut ws = WinSize::default();
        // SAFETY: `isatty` only inspects the descriptor and `TIOCGWINSZ`
        // fills in a `struct winsize`, which `WinSize` mirrors exactly.
        let ok = unsafe { isatty(fd) == 1 && ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) != -1 };
        if ok && ws.ws_col > 0 && ws.ws_row > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

#[cfg(not(any(target_os = "linux", target_os = "android")))]
mod sys {
    use super::{Height, Width};

    pub(super) fn size_of_fd(_fd: i32) -> Option<(Width, Height)> {
        None
    }
}
